def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full-length separator color is the grid's partition color.
    freq = {}
    for row in grid:
        for v in row:
            if v:
                freq[v] = freq.get(v, 0) + 1
    wall = max(freq, key=freq.get)
    row_seps = [r for r in range(h) if all(v == wall for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == wall for r in range(h))]
    rbounds = [-1] + row_seps + [h]
    cbounds = [-1] + col_seps + [w]
    row_ranges = [(rbounds[i]+1, rbounds[i+1]) for i in range(len(rbounds)-1)]
    col_ranges = [(cbounds[i]+1, cbounds[i+1]) for i in range(len(cbounds)-1)]
    nr, nc = len(row_ranges), len(col_ranges)
    cell_h = row_ranges[0][1] - row_ranges[0][0]
    cell_w = col_ranges[0][1] - col_ranges[0][0]

    # Each row of cells is keyed by the color of its marker in the leftmost cell.
    row_colors = []
    for r0, r1 in row_ranges:
        vals = [grid[r][c] for r in range(r0, r1) for c in range(col_ranges[0][0], col_ranges[0][1]) if grid[r][c] not in (0, wall)]
        counts = {}
        for v in vals:
            counts[v] = counts.get(v, 0) + 1
        row_colors.append(max(counts, key=counts.get))

    # The lone non-marker figure provides the shape to copy into every chamber.
    template = None
    marker_colors = set(row_colors)
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            if ci == 0:
                continue
            coords = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, wall) and grid[r][c] not in marker_colors]
            if coords:
                template = coords
                break
        if template is not None:
            break
    if template is None:
        # Fallback: choose the most populated non-left chamber.
        best = []
        for ri, (r0, r1) in enumerate(row_ranges):
            for ci, (c0, c1) in enumerate(col_ranges[1:], 1):
                coords = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, wall)]
                if len(coords) > len(best):
                    best = coords
        template = best

    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in row_seps:
        for c in range(w):
            out[r][c] = wall
    for c in col_seps:
        for r in range(h):
            out[r][c] = wall
    for ri, (r0, r1) in enumerate(row_ranges):
        color = row_colors[ri]
        for c0, c1 in col_ranges:
            for dr, dc in template:
                if dr < r1-r0 and dc < c1-c0:
                    out[r0+dr][c0+dc] = color
    return out
